pub fn parse_mf1_mt456(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_awr: f64 = 0.0;
    let mut var_eint: f64 = 0.0;
    let mut var_lnu: f64 = 0.0;
    let mut var_np: f64 = 0.0;
    let mut var_nr: f64 = 0.0;
    let mut var_nubar_p: f64 = 0.0;
    let mut var_za: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    // HEAD/CONT record
    {
        let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
        let (cont, _ctrl) = read_cont(_line_ref, read_opts)?;
        let _cont_origs = extract_cont_originals(_line_ref, read_opts);
        ofs += 1;
        var_za = cont.c1;
        result.insert("ZA", f64_to_endf_value_preserved(var_za, _cont_origs[0].clone()));
        var_awr = cont.c2;
        result.insert("AWR", f64_to_endf_value_preserved(var_awr, _cont_origs[1].clone()));
        if !values_match(0_f64, cont.l1 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.l1 as f64, field: "L1".to_string() });
            }
        }
        var_lnu = cont.l2 as f64;
        result.insert("LNU", EndfValue::Int(var_lnu as i64));
        if !values_match(0_f64, cont.n1 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.n1 as f64, field: "N1".to_string() });
            }
        }
        if !values_match(0_f64, cont.n2 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.n2 as f64, field: "N2".to_string() });
            }
        }
    }
    if (var_lnu as f64 as i64) == (2_f64 as i64) {
        // TAB1 record
        {
            let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
            let (cont, _ctrl) = read_cont(_line_ref, read_opts)?;
            let _cont_origs = extract_cont_originals(_line_ref, read_opts);
            ofs += 1;

            if !values_match(0_f64, cont.c1, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.c1, field: "C1".to_string() });
                }
            }
            if !values_match(0_f64, cont.c2, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.c2, field: "C2".to_string() });
                }
            }
            if !values_match(0_f64, cont.l1 as f64, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.l1 as f64, field: "L1".to_string() });
                }
            }
            if !values_match(0_f64, cont.l2 as f64, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.l2 as f64, field: "L2".to_string() });
                }
            }

            let _nr = cont.n1 as usize;
            let _np = cont.n2 as usize;
            let _body_lines: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
            let (_body, _body_consumed, _x_origs, _y_origs) = read_tab1_body(&_body_lines, 0, _nr, _np, read_opts)?;
            ofs += _body_consumed;

            result.insert("NBT", list_from_i64(&_body.nbt));
            result.insert("INT", list_from_i64(&_body.int));
            result.insert("Eint", list_from_f64_preserved(&_body.x, &_x_origs));
            result.insert("nubar_p", list_from_f64_preserved(&_body.y, &_y_origs));
        }
    } else if (var_lnu as f64 as i64) == (1_f64 as i64) {
        // LIST record
        {
            let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
            let _line_ref_str: &str = _line_ref.as_str();
            let (cont, _ctrl) = read_cont(_line_ref_str, read_opts)?;
            let _cont_origs = extract_cont_originals(_line_ref_str, read_opts);
            ofs += 1;
            let _npl = cont.n1 as usize;
            let _body_lines: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
            let (_vals_with_origs, _body_end) = if _npl > 0 { read_endf_numbers(&_body_lines, _npl, 0, read_opts)? } else { (Vec::new(), 0) };
            ofs += _body_end;
            let vals: Vec<f64> = _vals_with_origs.iter().map(|(v, _)| *v).collect();

            if !values_match(0_f64, cont.c1, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.c1, field: "C1".to_string() });
                }
            }
            if !values_match(0_f64, cont.c2, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.c2, field: "C2".to_string() });
                }
            }
            if !values_match(0_f64, cont.l1 as f64, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.l1 as f64, field: "L1".to_string() });
                }
            }
            if !values_match(0_f64, cont.l2 as f64, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.l2 as f64, field: "L2".to_string() });
                }
            }
            if !values_match(1_f64, cont.n1 as f64, parse_opts) {
                return Err(EndfError::NumberMismatch { expected: 1_f64, got: cont.n1 as f64, field: "N1".to_string() });
            }
            if !values_match(0_f64, cont.n2 as f64, parse_opts) {
                if !parse_opts.ignore_zero_mismatch {
                    return Err(EndfError::ZeroMismatch { got: cont.n2 as f64, field: "N2".to_string() });
                }
            }

            let mut vi: usize = 0;
            let _val = vals[vi];
            let _orig = _vals_with_origs[vi].1.clone();
            result.insert("nubar_p", f64_to_endf_value_preserved(_val, _orig));
            var_nubar_p = _val;
            vi += 1;
        }
    }
    // SEND
    Ok(result)
}

pub fn write_mf1_mt456(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    let _saved_data = data;  // top-level scope fallback
    // Write HEAD/CONT
    lines.push(write_cont_preserved(&get_endf_value_or_zero(data, "ZA"), &get_endf_value_or_zero(data, "AWR"), 0_f64 as i64, get_int_field(data, "LNU", "L2", write_opts)?, 0_f64 as i64, 0_f64 as i64, &ctrl, write_opts));
    if (data.get("LNU").or_else(|| _saved_data.get("LNU")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (2_f64 as i64) {
        // Write TAB1
        let _tab_scope = &data;
        let _nbt = get_int_vec(_tab_scope, "NBT");
        let _int = get_int_vec(_tab_scope, "INT");
        let _x_vals = get_endf_value_vec(_tab_scope, "Eint");
        let _y_vals = get_endf_value_vec(_tab_scope, "nubar_p");
        let _nr = _nbt.len() as i64;
        let _np = _x_vals.len() as i64;
        lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), 0_f64 as i64, 0_f64 as i64, _nr, _np, &ctrl, write_opts));
        lines.extend(write_tab1_body_preserved(&_nbt, &_int, &_x_vals, &_y_vals, &ctrl, write_opts));
    } else if (data.get("LNU").or_else(|| _saved_data.get("LNU")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (1_f64 as i64) {
        // Write LIST
        let mut _ev_vals: Vec<EndfValue> = Vec::new();
        let _list_scope = &data;
        _ev_vals.push(get_endf_value_or_zero(_list_scope, "nubar_p"));
        lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), 0_f64 as i64, 0_f64 as i64, _ev_vals.len() as i64, 0_f64 as i64, &ctrl, write_opts));
        let _ev_refs: Vec<&EndfValue> = _ev_vals.iter().collect();
        lines.extend(write_endf_values(&_ev_refs, &ctrl, false, write_opts));
    }
    // SEND
    Ok(lines)
}

