            let _orig = _vals_with_origs[vi].1.clone();
            result.insert("EGP", f64_to_endf_value_preserved(_val, _orig));
            var_egp = _val;
            vi += 1;
            let _val = vals[vi];
            let _orig = _vals_with_origs[vi].1.clone();
            result.insert("dEGP", f64_to_endf_value_preserved(_val, _orig));
            var_degp = _val;
