pub fn write_mf1_mt460(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    let _saved_data = data;  // top-level scope fallback
    if (data.get("LO").or_else(|| _saved_data.get("LO")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (1_f64 as i64) {
        // Write HEAD/CONT
        lines.push(write_cont_preserved(&get_endf_value_or_zero(data, "ZA"), &get_endf_value_or_zero(data, "AWR"), get_int_field(data, "LO", "L1", write_opts)?, 0_f64 as i64, get_int_field(data, "NG", "N1", write_opts)?, 0_f64 as i64, &ctrl, write_opts));
        for _i_i in (1_f64 as i64)..=(data.get("NG").or_else(|| _saved_data.get("NG")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
            // Write TAB1
            let _tab_scope = &data.get("table").and_then(|d| get_indexed(d, _i_i as f64 as i64)).unwrap();
            let _nbt = get_int_vec(_tab_scope, "NBT");
            let _int = get_int_vec(_tab_scope, "INT");
            let _x_vals = get_endf_value_vec(_tab_scope, "tint");
            let _y_vals = get_endf_value_vec(_tab_scope, "T");
            let _nr = _nbt.len() as i64;
            let _np = _x_vals.len() as i64;
            lines.push(write_cont_preserved(&EndfValue::Float(data.get("E").and_then(|d| get_indexed(d, _i_i as f64 as i64)).and_then(|v| v.as_float()).unwrap_or(0.0)), &EndfValue::Float(0_f64), _i_i as f64 as i64, 0_f64 as i64, _nr, _np, &ctrl, write_opts));
            lines.extend(write_tab1_body_preserved(&_nbt, &_int, &_x_vals, &_y_vals, &ctrl, write_opts));
        }
    } else if (data.get("LO").or_else(|| _saved_data.get("LO")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (2_f64 as i64) {
        // Write HEAD/CONT
        lines.push(write_cont_preserved(&get_endf_value_or_zero(data, "ZA"), &get_endf_value_or_zero(data, "AWR"), get_int_field(data, "LO", "L1", write_opts)?, 0_f64 as i64, 0_f64 as i64, 0_f64 as i64, &ctrl, write_opts));
        // Write LIST
        let mut _ev_vals: Vec<EndfValue> = Vec::new();
        let _list_scope = &data;
        for _i_i in (1_f64 as i64)..=(data.get("NNF").or_else(|| _saved_data.get("NNF")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
            _ev_vals.push(EndfValue::Float(_list_scope.get("lambda").and_then(|d| get_indexed(d, _i_i as f64 as i64)).and_then(|v| v.as_float()).unwrap_or(0.0)));
        }
        lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), 0_f64 as i64, 0_f64 as i64, _ev_vals.len() as i64, 0_f64 as i64, &ctrl, write_opts));
        let _ev_refs: Vec<&EndfValue> = _ev_vals.iter().collect();
        lines.extend(write_endf_values(&_ev_refs, &ctrl, false, write_opts));
    }
    // SEND
    Ok(lines)
}

