pub fn parse_mf10_wildcard(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_awr: f64 = 0.0;
    let mut var_e: f64 = 0.0;
    let mut var_izap: f64 = 0.0;
    let mut var_k: f64 = 0.0;
    let mut var_lfs: f64 = 0.0;
    let mut var_lis: f64 = 0.0;
    let mut var_np: f64 = 0.0;
    let mut var_nr: f64 = 0.0;
    let mut var_ns: f64 = 0.0;
    let mut var_qi: f64 = 0.0;
    let mut var_qm: f64 = 0.0;
    let mut var_sigma: f64 = 0.0;
    let mut var_subsection: f64 = 0.0;
    let mut var_za: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    // HEAD/CONT record
    {
        let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
        let (cont, _ctrl) = read_cont(_line_ref, read_opts)?;
        let _cont_origs = extract_cont_originals(_line_ref, read_opts);
        ofs += 1;
        var_za = cont.c1;
        result.insert("ZA", f64_to_endf_value_preserved(var_za, _cont_origs[0].clone()));
        var_awr = cont.c2;
        result.insert("AWR", f64_to_endf_value_preserved(var_awr, _cont_origs[1].clone()));
        var_lis = cont.l1 as f64;
        result.insert("LIS", EndfValue::Int(var_lis as i64));
        if !values_match(0_f64, cont.l2 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.l2 as f64, field: "L2".to_string() });
            }
        }
        var_ns = cont.n1 as f64;
        result.insert("NS", EndfValue::Int(var_ns as i64));
        if !values_match(0_f64, cont.n2 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.n2 as f64, field: "N2".to_string() });
            }
        }
    }
    for var_k_loop_ in (1_f64 as i64)..=(var_ns as f64 as i64) {
        var_k = var_k_loop_ as f64;
        // Section: subsection
        {
            let mut section_subsection = EndfValue::new_dict();
            std::mem::swap(&mut result, &mut section_subsection);
            // TAB1 record
            {
                let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
                let (cont, _ctrl) = read_cont(_line_ref, read_opts)?;
                let _cont_origs = extract_cont_originals(_line_ref, read_opts);
                ofs += 1;

                var_qm = cont.c1;
                result.insert("QM", f64_to_endf_value_preserved(var_qm, _cont_origs[0].clone()));
                var_qi = cont.c2;
                result.insert("QI", f64_to_endf_value_preserved(var_qi, _cont_origs[1].clone()));
                var_izap = cont.l1 as f64;
                result.insert("IZAP", EndfValue::Int(var_izap as i64));
                var_lfs = cont.l2 as f64;
                result.insert("LFS", EndfValue::Int(var_lfs as i64));

                let _nr = cont.n1 as usize;
                let _np = cont.n2 as usize;
                let _body_lines: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
                let (_body, _body_consumed, _x_origs, _y_origs) = read_tab1_body(&_body_lines, 0, _nr, _np, read_opts)?;
                ofs += _body_consumed;

                result.insert("NBT", list_from_i64(&_body.nbt));
                result.insert("INT", list_from_i64(&_body.int));
                result.insert("E", list_from_f64_preserved(&_body.x, &_x_origs));
                result.insert("sigma", list_from_f64_preserved(&_body.y, &_y_origs));
            }
            std::mem::swap(&mut result, &mut section_subsection);
            if !result.contains_key("subsection") {
                result.insert("subsection", make_container(parse_opts));
            }
            {
                let _scope = result.get_mut("subsection").unwrap();
                insert_indexed(_scope, var_k as f64 as i64, section_subsection);
            }
        }
    }
    // SEND
    Ok(result)
}

