pub fn write_mf31_wildcard(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    let _saved_data = data;  // top-level scope fallback
    // Write HEAD/CONT
    lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), 0_f64 as i64, get_int_field(data, "LTY", "L2", write_opts)?, 0_f64 as i64, 0_f64 as i64, &ctrl, write_opts));
    if (data.get("LTY").or_else(|| _saved_data.get("LTY")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (0_f64 as i64) {
        // Write LIST
        let mut _ev_vals: Vec<EndfValue> = Vec::new();
        let _list_scope = &data;
        for _i_k in (1_f64 as i64)..=(data.get("NCI").or_else(|| _saved_data.get("NCI")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
            _ev_vals.push(EndfValue::Float(_list_scope.get("CI").and_then(|d| get_indexed(d, _i_k as f64 as i64)).and_then(|v| v.as_float()).unwrap_or(0.0)));
            _ev_vals.push(EndfValue::Float(_list_scope.get("XMTI").and_then(|d| get_indexed(d, _i_k as f64 as i64)).and_then(|v| v.as_float()).unwrap_or(0.0)));
        }
        lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), 0_f64 as i64, 0_f64 as i64, _ev_vals.len() as i64, get_int_field(data, "NCI", "N2", write_opts)?, &ctrl, write_opts));
        let _ev_refs: Vec<&EndfValue> = _ev_vals.iter().collect();
        lines.extend(write_endf_values(&_ev_refs, &ctrl, false, write_opts));
    } else if (((data.get("LTY").or_else(|| _saved_data.get("LTY")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (1_f64 as i64)) || ((data.get("LTY").or_else(|| _saved_data.get("LTY")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (2_f64 as i64))) || ((data.get("LTY").or_else(|| _saved_data.get("LTY")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (3_f64 as i64)) {
        // Write LIST
        let mut _ev_vals: Vec<EndfValue> = Vec::new();
        let _list_scope = &data;
        _ev_vals.push(get_endf_value_or_zero(_list_scope, "XMFS"));
        _ev_vals.push(get_endf_value_or_zero(_list_scope, "XLFSS"));
        _ev_vals.push(EndfValue::Float(0_f64));
        _ev_vals.push(get_endf_value_or_zero(_list_scope, "Weight"));
        lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), get_int_field(data, "MATS", "L1", write_opts)?, get_int_field(data, "MTS", "L2", write_opts)?, _ev_vals.len() as i64, 1_f64 as i64, &ctrl, write_opts));
        let _ev_refs: Vec<&EndfValue> = _ev_vals.iter().collect();
        lines.extend(write_endf_values(&_ev_refs, &ctrl, false, write_opts));
    } else {
    }
    // SEND
    Ok(lines)
}

