pub fn parse_mf35_wildcard(
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    let mut ofs: usize = 0;
    let mut result = EndfValue::new_dict();
    let mut var_awr: f64 = 0.0;
    let mut var_e: f64 = 0.0;
    let mut var_e1: f64 = 0.0;
    let mut var_e2: f64 = 0.0;
    let mut var_f: f64 = 0.0;
    let mut var_i: f64 = 0.0;
    let mut var_j: f64 = 0.0;
    let mut var_k: f64 = 0.0;
    let mut var_lb: f64 = 0.0;
    let mut var_ls: f64 = 0.0;
    let mut var_ne: f64 = 0.0;
    let mut var_nk: f64 = 0.0;
    let mut var_nt: f64 = 0.0;
    let mut var_subsection: f64 = 0.0;
    let mut var_za: f64 = 0.0;

    if !lines.is_empty() {
        let ctrl = records::read_ctrl(&lines[0], read_opts)?;
        result.insert("MAT", EndfValue::Int(ctrl.mat as i64));
        result.insert("MF", EndfValue::Int(ctrl.mf as i64));
        result.insert("MT", EndfValue::Int(ctrl.mt as i64));
    }
    // HEAD/CONT record
    {
        let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
        let (cont, _ctrl) = read_cont(_line_ref, read_opts)?;
        let _cont_origs = extract_cont_originals(_line_ref, read_opts);
        ofs += 1;
        var_za = cont.c1;
        result.insert("ZA", f64_to_endf_value_preserved(var_za, _cont_origs[0].clone()));
        var_awr = cont.c2;
        result.insert("AWR", f64_to_endf_value_preserved(var_awr, _cont_origs[1].clone()));
        if !values_match(0_f64, cont.l1 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.l1 as f64, field: "L1".to_string() });
            }
        }
        if !values_match(0_f64, cont.l2 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.l2 as f64, field: "L2".to_string() });
            }
        }
        var_nk = cont.n1 as f64;
        result.insert("NK", EndfValue::Int(var_nk as i64));
        if !values_match(0_f64, cont.n2 as f64, parse_opts) {
            if !parse_opts.ignore_zero_mismatch {
                return Err(EndfError::ZeroMismatch { got: cont.n2 as f64, field: "N2".to_string() });
            }
        }
    }
    for var_k_loop_ in (1_f64 as i64)..=(var_nk as f64 as i64) {
        var_k = var_k_loop_ as f64;
        // Section: subsection
        {
            let mut section_subsection = EndfValue::new_dict();
            std::mem::swap(&mut result, &mut section_subsection);
            let lookahead_ok_0 = {
                let saved_ofs = ofs;
                let ok = (|| -> Result<bool, EndfError> {
                    if ofs + 0 >= lines.len() { return Ok(false); }
                    let (cont_0, _ctrl) = read_cont(&lines[ofs + 0], read_opts)?;
                    var_e1 = cont_0.c1;
                    var_e2 = cont_0.c2;
                    var_ls = cont_0.l1 as f64;
                    var_lb = cont_0.l2 as f64;
                    var_nt = cont_0.n1 as f64;
                    var_ne = cont_0.n2 as f64;
                    Ok(((var_ls as f64 as i64) == (1_f64 as i64)) && ((var_lb as f64 as i64) == (7_f64 as i64)))
                })().unwrap_or(false);
                ok
            };
            if lookahead_ok_0 {
                // LIST record
                {
                    let _line_ref = lines.get(ofs).ok_or(EndfError::UnexpectedEndOfInput { line: ofs })?;
                    let _line_ref_str: &str = _line_ref.as_str();
                    let (cont, _ctrl) = read_cont(_line_ref_str, read_opts)?;
                    let _cont_origs = extract_cont_originals(_line_ref_str, read_opts);
                    ofs += 1;
                    let _npl = cont.n1 as usize;
                    let _body_lines: Vec<&str> = lines[ofs..].iter().map(|s| s.as_str()).collect();
                    let (_vals_with_origs, _body_end) = if _npl > 0 { read_endf_numbers(&_body_lines, _npl, 0, read_opts)? } else { (Vec::new(), 0) };
                    ofs += _body_end;
                    let vals: Vec<f64> = _vals_with_origs.iter().map(|(v, _)| *v).collect();

                    var_e1 = cont.c1;
                    result.insert("E1", f64_to_endf_value_preserved(var_e1, _cont_origs[0].clone()));
                    var_e2 = cont.c2;
                    result.insert("E2", f64_to_endf_value_preserved(var_e2, _cont_origs[1].clone()));
                    var_ls = cont.l1 as f64;
                    result.insert("LS", EndfValue::Int(var_ls as i64));
                    var_lb = cont.l2 as f64;
                    result.insert("LB", EndfValue::Int(var_lb as i64));
                    var_nt = cont.n1 as f64;
                    result.insert("NT", EndfValue::Int(var_nt as i64));
                    var_ne = cont.n2 as f64;
                    result.insert("NE", EndfValue::Int(var_ne as i64));

                    let mut vi: usize = 0;
                    if (1_f64 as i64) <= (var_ne as f64 as i64) {
                        if !result.contains_key("E") { result.insert("E", make_container(parse_opts)); }
                    }
                    for var_i_loop_ in (1_f64 as i64)..=(var_ne as f64 as i64) {
                        var_i = var_i_loop_ as f64;
                        let _val = vals[vi];
                        let _orig = _vals_with_origs[vi].1.clone();
                        {
                            let _scope = result.get_mut("E").unwrap();
                            insert_indexed(_scope, var_i as f64 as i64, f64_to_endf_value_preserved(_val, _orig));
                        }
                        vi += 1;
                    }
                    if (1_f64 as i64) <= ((var_ne as f64 - 1_f64) as i64) {
                        if !result.contains_key("F") { result.insert("F", make_container(parse_opts)); }
                    }
                    for var_i_loop_ in (1_f64 as i64)..=((var_ne as f64 - 1_f64) as i64) {
                        var_i = var_i_loop_ as f64;
                        if (var_i as f64 as i64) <= ((var_ne as f64 - 1_f64) as i64) {
                            if !result.contains_key("F") { result.insert("F", make_container(parse_opts)); }
                        }
                        for var_j_loop_ in (var_i as f64 as i64)..=((var_ne as f64 - 1_f64) as i64) {
                            var_j = var_j_loop_ as f64;
                            let _val = vals[vi];
                            let _orig = _vals_with_origs[vi].1.clone();
                            {
                                let _scope = result.get_mut("F").unwrap();
                                if !contains_indexed(_scope, var_i as f64 as i64) { insert_indexed(_scope, var_i as f64 as i64, make_container(parse_opts)); }
                                let _scope = get_indexed_mut(_scope, var_i as f64 as i64).unwrap();
                                insert_indexed(_scope, var_j as f64 as i64, f64_to_endf_value_preserved(_val, _orig));
                            }
                            vi += 1;
                        }
                    }
                }
            }
            std::mem::swap(&mut result, &mut section_subsection);
            if !result.contains_key("subsection") {
                result.insert("subsection", make_container(parse_opts));
            }
            {
                let _scope = result.get_mut("subsection").unwrap();
                insert_indexed(_scope, var_k as f64 as i64, section_subsection);
            }
        }
    }
    // SEND
    Ok(result)
}

pub fn write_mf35_wildcard(
    data: &EndfValue,
    write_opts: &WriteOpts,
) -> EndfResult<Vec<String>> {
    let mut lines: Vec<String> = Vec::new();
    let ctrl = get_ctrl(data);
    let _saved_data = data;  // top-level scope fallback
    // Write HEAD/CONT
    lines.push(write_cont_preserved(&get_endf_value_or_zero(data, "ZA"), &get_endf_value_or_zero(data, "AWR"), 0_f64 as i64, 0_f64 as i64, get_int_field(data, "NK", "N1", write_opts)?, 0_f64 as i64, &ctrl, write_opts));
    for _i_k in (1_f64 as i64)..=(data.get("NK").or_else(|| _saved_data.get("NK")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
        // Write section: subsection
        {
            let _saved_data = data;
            let data = data.get("subsection").and_then(|d| get_indexed(d, _i_k as f64 as i64)).unwrap();
            if ((data.get("LS").or_else(|| _saved_data.get("LS")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (1_f64 as i64)) && ((data.get("LB").or_else(|| _saved_data.get("LB")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) == (7_f64 as i64)) {
                // Write LIST
                let mut _ev_vals: Vec<EndfValue> = Vec::new();
                let _list_scope = &data;
                for _i_i in (1_f64 as i64)..=(data.get("NE").or_else(|| _saved_data.get("NE")).and_then(|v| v.as_float()).unwrap_or(0.0) as i64) {
                    _ev_vals.push(EndfValue::Float(_list_scope.get("E").and_then(|d| get_indexed(d, _i_i as f64 as i64)).and_then(|v| v.as_float()).unwrap_or(0.0)));
                }
                for _i_i in (1_f64 as i64)..=((data.get("NE").or_else(|| _saved_data.get("NE")).and_then(|v| v.as_float()).unwrap_or(0.0) - 1_f64) as i64) {
                    for _i_j in (_i_i as f64 as i64)..=((data.get("NE").or_else(|| _saved_data.get("NE")).and_then(|v| v.as_float()).unwrap_or(0.0) - 1_f64) as i64) {
                        _ev_vals.push(EndfValue::Float(_list_scope.get("F").and_then(|d| get_indexed(d, _i_i as f64 as i64)).and_then(|d| get_indexed(d, _i_j as f64 as i64)).and_then(|v| v.as_float()).unwrap_or(0.0)));
                    }
                }
                lines.push(write_cont_preserved(&get_endf_value_or_zero(data, "E1"), &get_endf_value_or_zero(data, "E2"), get_int_field(data, "LS", "L1", write_opts)?, get_int_field(data, "LB", "L2", write_opts)?, _ev_vals.len() as i64, get_int_field(data, "NE", "N2", write_opts)?, &ctrl, write_opts));
                let _ev_refs: Vec<&EndfValue> = _ev_vals.iter().collect();
                lines.extend(write_endf_values(&_ev_refs, &ctrl, false, write_opts));
            }
            let data = _saved_data;
        }
    }
    // SEND
    Ok(lines)
}

