                                lines.push(write_cont_preserved(&EndfValue::Float(0_f64), &EndfValue::Float(0_f64), 0_f64 as i64, get_int_field(data, "LB", "L2", write_opts)?, _ev_vals.len() as i64, get_int_field(data, "NER", "N2", write_opts)?, &ctrl, write_opts));
