/// Dispatch to the compiled parse function for the given MF/MT.
pub fn parse_section(
    mf: i32,
    mt: i32,
    lines: &[String],
    read_opts: &ReadOpts,
    parse_opts: &ParseOpts,
) -> EndfResult<EndfValue> {
    match (mf, mt) {
        (0, 0) => parse_mf0_mt0(lines, read_opts, parse_opts),
        (1, 451) => parse_mf1_mt451(lines, read_opts, parse_opts),
        (1, 452) => parse_mf1_mt452(lines, read_opts, parse_opts),
        (1, 455) => parse_mf1_mt455(lines, read_opts, parse_opts),
        (1, 456) => parse_mf1_mt456(lines, read_opts, parse_opts),
        (1, 458) => parse_mf1_mt458(lines, read_opts, parse_opts),
        (1, 460) => parse_mf1_mt460(lines, read_opts, parse_opts),
        (2, 151) => parse_mf2_mt151(lines, read_opts, parse_opts),
        (7, 2) => parse_mf7_mt2(lines, read_opts, parse_opts),
        (7, 4) => parse_mf7_mt4(lines, read_opts, parse_opts),
        (7, 451) => parse_mf7_mt451(lines, read_opts, parse_opts),
        (8, 454) => parse_mf8_mt454(lines, read_opts, parse_opts),
        (8, 457) => parse_mf8_mt457(lines, read_opts, parse_opts),
        (8, 459) => parse_mf8_mt459(lines, read_opts, parse_opts),
        (31, 452) => parse_mf31_mt452(lines, read_opts, parse_opts),
        (31, 455) => parse_mf31_mt455(lines, read_opts, parse_opts),
        (31, 456) => parse_mf31_mt456(lines, read_opts, parse_opts),
        (3, _) => parse_mf3_wildcard(lines, read_opts, parse_opts),
        (4, _) => parse_mf4_wildcard(lines, read_opts, parse_opts),
        (5, _) => parse_mf5_wildcard(lines, read_opts, parse_opts),
        (6, _) => parse_mf6_wildcard(lines, read_opts, parse_opts),
        (8, _) => parse_mf8_wildcard(lines, read_opts, parse_opts),
        (9, _) => parse_mf9_wildcard(lines, read_opts, parse_opts),
        (10, _) => parse_mf10_wildcard(lines, read_opts, parse_opts),
        (12, _) => parse_mf12_wildcard(lines, read_opts, parse_opts),
        (13, _) => parse_mf13_wildcard(lines, read_opts, parse_opts),
        (14, _) => parse_mf14_wildcard(lines, read_opts, parse_opts),
        (15, _) => parse_mf15_wildcard(lines, read_opts, parse_opts),
        (23, _) => parse_mf23_wildcard(lines, read_opts, parse_opts),
        (26, _) => parse_mf26_wildcard(lines, read_opts, parse_opts),
        (27, _) => parse_mf27_wildcard(lines, read_opts, parse_opts),
        (28, _) => parse_mf28_wildcard(lines, read_opts, parse_opts),
        (31, _) => parse_mf31_wildcard(lines, read_opts, parse_opts),
        (32, _) => parse_mf32_wildcard(lines, read_opts, parse_opts),
        (33, _) => parse_mf33_wildcard(lines, read_opts, parse_opts),
        (34, _) => parse_mf34_wildcard(lines, read_opts, parse_opts),
        (35, _) => parse_mf35_wildcard(lines, read_opts, parse_opts),
        (40, _) => parse_mf40_wildcard(lines, read_opts, parse_opts),
        _ => Err(EndfError::RecipeParse {
            message: format!("no compiled parser for MF{}/MT{}", mf, mt),
        }),
    }
}

